//! Port of tools/generate_ui_art.py: the carved-wood interface art in
//! `assets/ui/` -- the seamless wood tiles, the nine-slice card frame and the
//! `menu_*.png` emblems. `examples/generate_ui_art.rs` writes them.
//!
//! Not ported: the three mode pictures (`mode_*.png`) and the app icon burn
//! the real procedural tarantula into the wood, which needs the creature
//! simulation and painter (dc-creature / dc-paint); they stay generated by the
//! Python tool until those crates land.
//!
//! The wood grain is pure arithmetic on CPython's `random.Random(seed)`
//! stream, so the tiles come out value for value; the carving is painted
//! with `dc-render`.

use std::f64::consts::{PI, TAU};

use dc_core::{Color, PyRandom, Rect};
