// -- wood grain ------------------------------------------------------------------------

/// Periodic value noise, so a texture can tile without a seam.
pub struct Noise {
    table: Vec<f64>,
}

impl Noise {
    pub fn new(seed: i64) -> Self {
        let mut rng = PyRandom::from_int(seed as i128);
        Noise { table: (0..256 * 256).map(|_| rng.random()).collect() }
    }

    pub fn value(&self, x: f64, y: f64, px: i64, py: i64) -> f64 {
        let (ix, iy) = (x.floor(), y.floor());
        let (fx, fy) = (x - ix, y - iy);
        let (sx, sy) = (fx * fx * (3.0 - 2.0 * fx), fy * fy * (3.0 - 2.0 * fy));
        let (ix, iy) = (ix as i64, iy as i64);
        let (x0, x1) = (ix.rem_euclid(px) as usize, (ix + 1).rem_euclid(px) as usize);
        let (y0, y1) = (iy.rem_euclid(py) as usize, (iy + 1).rem_euclid(py) as usize);
        let t = &self.table;
        let (a, b) = (t[y0 * 256 + x0], t[y0 * 256 + x1]);
        let (c, d) = (t[y1 * 256 + x0], t[y1 * 256 + x1]);
        let top = a + (b - a) * sx;
        let bottom = c + (d - c) * sx;
        top + (bottom - top) * sy
    }
}

/// `wood(width, height, light, dark, seed, rings, warp_amount)`:
/// plain-sawn grain running left to right; tiles in both directions. Opaque.
pub fn wood(width: u32, height: u32, light: (u8, u8, u8), dark: (u8, u8, u8), seed: i64, rings: i64, warp_amount: f64) -> Image {
    let noise = Noise::new(seed);
    let mut data = vec![0u8; (width * height * 4) as usize];
    let lerp = |l: u8, d: u8, t: f64| (l as f64 + (d as f64 - l as f64) * t) as u8;
    for y in 0..height {
        let v = y as f64 / height as f64;
        for x in 0..width {
            let u = x as f64 / width as f64;
            let warp = noise.value(u * 3.0, v * 5.0, 3, 5) * 0.65 + noise.value(u * 7.0, v * 11.0, 7, 11) * 0.35;
            let ring = 0.5 + 0.5 * ((v * rings as f64 + warp * warp_amount) * TAU).sin();
            let ring = ring.powf(6.0);
            // Fine fibres: long streaks along the grain, sharpened into lines.
            let fibre = noise.value(u * 4.0, v * 220.0, 4, 220).powf(2.2);
            let fleck = noise.value(u * 9.0, v * 90.0, 9, 90);
            let t = (0.46 * ring + 0.30 * fibre + 0.10 * warp + 0.14 * fleck).clamp(0.0, 1.0);
            let i = ((y * width + x) * 4) as usize;
            data[i] = lerp(light.0, dark.0, t);
            data[i + 1] = lerp(light.1, dark.1, t);
            data[i + 2] = lerp(light.2, dark.2, t);
            data[i + 3] = 255;
        }
    }
    Image::from_premultiplied(width, height, data).expect("wood size")
}

// -- carving -----------------------------------------------------------------------------

/// `_outside(path, bounds)`: a frame well beyond `bounds`, minus the path
/// (odd-even, so the path's inside is the hole).
pub fn outside(path: &Path, bounds: Rect) -> Path {
    let mut frame = Path::new();
    frame.add_rect(bounds.adjusted(-200.0, -200.0, 200.0, 200.0));
    frame.add_path(path);
    frame.set_fill_rule(FillRule::OddEven);
    frame
}

/// Carve `path` into the surface: a floor in shadow, lit on the far lip.
pub fn recess(p: &mut Canvas, path: &Path, depth: f64, shade: u8) {
    let bounds = path.bounding_rect();
    p.save();
    p.set_clip_path(path);
    p.fill_path(path, Color::rgba(30, 15, 5, shade));
    let out = outside(path, bounds);
    p.set_pen(Pen::NONE);
    let steps = 8;
    for i in (1..=steps).rev() {
        let d = depth * i as f64 / steps as f64;
        p.set_brush(Color::rgba(20, 9, 2, (34.0 * (1.0 - (i - 1) as f64 / steps as f64)) as u8));
        p.draw_path(&out.translated(d * 0.8, d));
    }
    for i in 1..4 {
        p.set_brush(Color::rgba(255, 226, 170, 26));
        p.draw_path(&out.translated(-i as f64 * 0.7, -i as f64 * 0.8));
    }
    p.restore();
    // The lit top edge of the cut, outside the recess.
    p.save();
    p.set_clip_path(&outside(path, bounds));
    p.set_pen(Pen::new(Color::rgba(255, 230, 180, 70), 1.4));
    p.set_brush(Brush::None);
    p.draw_path(&path.translated(0.9, 1.1));
    p.restore();
}

/// Raise `path` out of the surface: shadow below right, light above left.
pub fn relief(p: &mut Canvas, path: &Path, height: f64, fill: Option<Brush>) {
    p.save();
    p.set_pen(Pen::NONE);
    for i in (1..=6).rev() {
        let d = height * i as f64 / 6.0;
        p.set_brush(Color::rgba(20, 9, 2, 22));
        p.draw_path(&path.translated(d * 0.7, d));
    }
    if let Some(fill) = fill {
        p.set_brush(fill);
        p.draw_path(path);
    }
    p.set_clip_path(path);
    let out = outside(path, path.bounding_rect());
    for i in 1..4 {
        p.set_brush(Color::rgba(255, 232, 186, 34));
        p.draw_path(&out.translated(i as f64 * 0.8, i as f64 * 0.9));
    }
    for i in 1..4 {
        p.set_brush(Color::rgba(20, 9, 2, 40));
        p.draw_path(&out.translated(-i as f64 * 0.8, -i as f64 * 0.9));
    }
    p.restore();
}

/// Pyrography: a scorched halo, then the dark line itself.
pub fn burn(p: &mut Canvas, path: &Path, width: f64, alpha: u8) {
    p.save();
    p.set_brush(Brush::None);
    for (w, a) in [(width * 4.0, 18), (width * 2.4, 36), (width * 1.5, 70)] {
        p.set_pen(round_pen(Color::rgba(60, 28, 8, a), w));
        p.draw_path(path);
    }
    p.set_pen(round_pen(Color::rgba(BURN.r, BURN.g, BURN.b, alpha), width));
    p.draw_path(path);
    p.restore();
}

/// A V-cut line: a dark channel with a lit lower lip.
pub fn groove(p: &mut Canvas, path: &Path, width: f64) {
    p.save();
    p.set_brush(Brush::None);
    p.set_pen(round_pen(Color::rgba(255, 228, 176, 90), width * 0.55));
    p.draw_path(&path.translated(width * 0.35, width * 0.45));
    p.set_pen(round_pen(Color::rgba(34, 16, 5, 215), width));
    p.draw_path(path);
    p.restore();
}

/// A brass or stained inlay set flush into the wood.
pub fn inlay(p: &mut Canvas, path: &Path, color: Color) {
    p.save();
    let b = path.bounding_rect();
    let grad = LinearGradient::new(b.x, b.y, b.right(), b.bottom())
        .with_stop(0.0, lighter(color, 135))
        .with_stop(0.55, color)
        .with_stop(1.0, darker(color, 140));
    p.set_pen(Pen::new(Color::rgba(30, 14, 4, 220), 1.6));
    p.set_brush(grad);
    p.draw_path(path);
    p.restore();
}

pub fn rounded(rect: Rect, radius: f64) -> Path {
    let mut path = Path::new();
    path.add_rounded_rect(rect, radius, radius);
    path
}

pub fn ellipse(cx: f64, cy: f64, rx: f64, ry: f64) -> Path {
    let mut path = Path::new();
    path.add_ellipse_c(cx, cy, rx, ry);
    path
}

pub fn polyline(points: &[(f64, f64)], closed: bool) -> Path {
    let mut path = Path::new();
    path.move_to(points[0].0, points[0].1);
    for pt in &points[1..] {
        path.line_to(pt.0, pt.1);
    }
    if closed {
        path.close_subpath();
    }
    path
}

/// A web from (cx, cy) between angles `a0` and `a1`, burned in.
pub fn web(p: &mut Canvas, cx: f64, cy: f64, radius: f64, a0: f64, a1: f64, spokes: usize, turns: usize) {
    let mut ends = Vec::new();
    for i in 0..spokes {
        let a = a0 + (a1 - a0) * i as f64 / (spokes - 1) as f64;
        ends.push(a);
        burn(p, &polyline(&[(cx, cy), (cx + a.cos() * radius, cy + a.sin() * radius)], false), 1.3, 235);
    }
    for k in 1..=turns {
        let r = radius * k as f64 / (turns as f64 + 0.6);
        let sag = if k % 2 == 1 { 0.93 } else { 0.97 };
        let pts: Vec<(f64, f64)> = ends.iter().map(|a| (cx + a.cos() * r * sag, cy + a.sin() * r * sag)).collect();
        burn(p, &polyline(&pts, false), 1.0, 200);
    }
}

/// A burned-in fly.
pub fn fly(p: &mut Canvas, x: f64, y: f64, s: f64) {
    for side in [-1.0, 1.0] {
        burn(p, &ellipse(x + side * 6.0 * s, y - 5.0 * s, 7.0 * s, 4.0 * s), 1.0, 160);
    }
    let body = ellipse(x, y, 4.5 * s, 7.0 * s);
    p.save();
    p.set_pen(Pen::NONE);
    p.set_brush(Color::rgba(40, 20, 8, 235));
    p.draw_path(&body);
    p.restore();
}

pub fn star(cx: f64, cy: f64, r_out: f64, r_in: f64, points: usize, rot: f64) -> Path {
    let pts: Vec<(f64, f64)> = (0..points * 2)
        .map(|i| {
            let r = if i % 2 == 0 { r_out } else { r_in };
            let a = rot + i as f64 * PI / points as f64;
            (cx + a.cos() * r, cy + a.sin() * r)
        })
        .collect();
    polyline(&pts, true)
}

/// `card_frame()`: a nine-slice frame, a carved border 28px wide around dark walnut.
pub fn card_frame() -> Image {
    let size = 160u32;
    let s = size as f64;
    let mut image = wood(size, size, WALNUT_LIGHT, WALNUT_DARK, 71, 3, 2.4);
    image.paint(|p| {
        p.set_render_hint(RenderHint::Antialiasing, true);
        relief(p, &rounded(Rect::new(4.0, 4.0, s - 8.0, s - 8.0), 16.0), 3.0, None);
        groove(p, &rounded(Rect::new(12.0, 12.0, s - 24.0, s - 24.0), 11.0), 2.0);
        recess(p, &rounded(Rect::new(22.0, 22.0, s - 44.0, s - 44.0), 8.0), 4.0, 30);
    });
    // Round the outer corners off to transparent.
    let mut out = Image::new(size, size);
    out.paint(|q| {
        q.set_render_hint(RenderHint::Antialiasing, true);
        q.set_clip_path(&rounded(Rect::new(0.0, 0.0, s, s), 18.0));
        q.draw_image_at(0.0, 0.0, &image);
    });
    out
}

